(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18+Math.cos(y*0.013-t*0.22)*12+Math.sin((x+y)*0.008+t*0.15)*8;
  const w1y = Math.cos(y*0.02-t*0.28)*16+Math.sin(x*0.016+t*0.33)*11+Math.cos((x-y)*0.009-t*0.18)*7;
  const w2x = Math.sin(x*0.035-t*0.5)*6+Math.cos(y*0.04+t*0.6)*5;
  const w2y = Math.cos(y*0.032+t*0.45)*6+Math.sin(x*0.038-t*0.55)*5;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.85],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.05],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+4)*50, 0.11, 2.1, 0.8],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+1)*55, 0.085, 1.8, 1.15]
  ];
  let aS=0, iS=0, cS=0;
  for(const[sX,sY,f,sp,w] of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const w1=Math.sin(d*f-t*sp), w2=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    const w3=Math.sin(d*f*1.4-t*sp*0.4+3.0)*0.4;
    aS+=(w1+w3)*w; iS+=(w2-w3*0.5)*w;
    cS+=Math.sin(d*f*2.1+t*sp*1.3+2.0)*0.3*w;
  }
  const act=aS/6.8, inh=iS/6.8, cor=cS/6.8;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2
    +Math.sin(sx*0.07+sy*0.05-t*1.8)*0.15+Math.cos(sx*0.09-sy*0.06+t*2.2)*0.12;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    +Math.sin(dist*0.08-ang*2+t*0.9)*0.2;
  const micro=(Math.sin(sx*0.4+sy*0.3+t*3)*Math.sin(sx*0.35-sy*0.45-t*2.5))*0.15;
  const pulse=Math.sin(t*0.4)*0.08+Math.sin(t*0.7)*0.05;
  const rd1=Math.tanh((act-inh*0.7+bg*0.3+spiral+pulse)*2.2);
  const rd2=Math.tanh((cor*1.5-inh*0.4+bg*0.2-micro)*2.8);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.22-sy*0.18+t*1.3)*0.3)*1.5)*0.3;
  const weave=Math.sin(sx*0.12+t*0.8)*Math.cos(sy*0.12-t*0.6)*0.15;
  const blend=rd1*0.5+rd2*0.2+cell*0.2+weave*0.1;
  const v=blend*0.5+0.5;
  const pal=[
    [5,12,52],[12,45,85],[18,95,115],[25,155,145],[180,175,60],
    [215,135,65],[195,80,70],[140,40,75],[70,18,55],[5,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.78+Math.sin(rd1*Math.PI)*0.22;
  const edgeR=Math.abs(rd1), edge=edgeR>0.65?1.0+edgeR*0.25:edgeR>0.4?1.05:1.0;
  const glow=Math.max(0,edgeR-0.6)*0.6;
  const r0=pal[i][0]+(pal[i+1][0]-pal[i][0])*f;
  const g0=pal[i][1]+(pal[i+1][1]-pal[i][1])*f;
  const b0=pal[i][2]+(pal[i+1][2]-pal[i][2])*f;
  return[
    Math.min(255,((r0*lum+glow*60)*edge))|0,
    Math.min(255,((g0*lum+glow*45)*edge))|0,
    Math.min(255,((b0*lum+glow*80)*edge))|0
  ];
}
